      <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes/date> ?d .
  FILTER(xsd:decimal(?ss) >= 97)
  FILTER(SUBSTR(STR(?d),1,4) >= "2013" && SUBSTR(STR(?d),1,4) <= "2015")
